// One proposal per blocking session (not one per blocked session).
const groups = {};
for (const { json: r } of $input.all()) {
  const g = groups[r.blocker_pid] ??= {
    blocker_pid: r.blocker_pid,
    blocker_user: r.blocker_user,
    blocker_ip: r.blocker_ip ?? 'local (socket)',
    blocker_application: r.blocker_application || null,
    blocker_state: r.blocker_state,
    blocker_query: r.blocker_query,
    blocker_tx_sec: r.blocker_tx_sec,
    max_wait_sec: 0,
    blocked: [],
  };
  g.blocked.push({ pid: r.blocked_pid, user: r.blocked_user, ip: r.blocked_ip ?? 'local (socket)', query: r.blocked_query, wait_sec: r.wait_sec });
  g.max_wait_sec = Math.max(g.max_wait_sec, r.wait_sec);
}

return Object.values(groups).map(g => ({
  json: {
    ...g,
    n_blocked: g.blocked.length,
    question: `Lock on PostgreSQL: maximum wait ${g.max_wait_sec} seconds, blocked sessions ${g.blocked.length}. Which severity should be assigned?`,
  },
}));

// Validates the Ollama response: if it is not valid JSON, fall back to cautious values.
const { question, ...s } = $('Group by Blocking Session').item.json;
const kb = $('Compose Prompt for Ollama').item.json;

let p = {};
try { p = JSON.parse($json.response); } catch (e) { p = {}; }

// The severity from the vector DB is authoritative; if the model reports a different one it is noted in the detail.
const model_severity = ['P1', 'P2', 'P3', 'P4'].includes(p.severity) ? p.severity : null;
const severity = kb.kb_severity ?? model_severity ?? 'P3';
const action = p.action === 'TERMINATE' ? 'TERMINATE' : 'WAIT';
const reason = String(p.reason || 'the model response could not be interpreted').slice(0, 300);

// Telegram parses the text as Markdown: the characters _ * ` [ must be preceded by \
// otherwise names such as app_user make the send fail ("can't parse entities").
const esc = v => String(v ?? '').replace(/([_*`\[])/g, '\\$1');
const message = [
  '🚨 Lock on PostgreSQL — severity ' + severity,
  '',
  `Blocker: pid ${s.blocker_pid} (${esc(s.blocker_state)}), transaction open for ${s.blocker_tx_sec} s`,
  `User: ${esc(s.blocker_user)}`,
  `Source IP: ${esc(s.blocker_ip)}` + (s.blocker_application ? ` (${esc(s.blocker_application)})` : ''),
  `Query: ${esc(s.blocker_query)}`,
  '',
  `Blocked sessions: ${s.n_blocked} (maximum wait ${s.max_wait_sec} s)`,
  ...s.blocked.slice(0, 5).map(b => `• pid ${b.pid}, user ${esc(b.user)}, IP ${esc(b.ip)}, waiting for ${b.wait_sec} s`),
  '',
  'AI proposal: ' + action,
  esc(reason),
  '',
  'Approve = terminate the blocking session.',
].join('\n');

return {
  json: {
    ...s,
    message,
    severity,
    action,
    reason,
    target: `pid=${s.blocker_pid}`,
    detail: {
      model: $('Set Configuration Parameters').first().json.model,
      proposed_action: action,
      kb_severity: kb.kb_severity,
      model_severity,
      kb_criterion: kb.kb_criterion,
      reason,
      blocker: { pid: s.blocker_pid, user: s.blocker_user, ip: s.blocker_ip, application: s.blocker_application, state: s.blocker_state, query: s.blocker_query, tx_sec: s.blocker_tx_sec },
      blocked: s.blocked,
    },
  },
};

// Builds the prompt from what was retrieved from the vector knowledge base.
const g = $('Group by Blocking Session').item.json;
const kb = $json;

const prompt = `You are a PostgreSQL DBA triaging locks. Use ONLY what the knowledge base reports.

SITUATION
- blocking session: pid ${g.blocker_pid}, user ${g.blocker_user}, state ${g.blocker_state}, transaction open for ${g.blocker_tx_sec} seconds
- blocking query: ${g.blocker_query}
- blocked sessions: ${g.n_blocked}
- maximum wait: ${g.max_wait_sec} seconds

KNOWLEDGE BASE
Criterion that applies to this situation: severity ${kb.kb_severity}
${kb.kb_criterion}

${kb.kb_context ?? ''}

Reply ONLY with a JSON object:
{"severity": "the severity stated by the applicable criterion", "action": "TERMINATE|WAIT according to the criterion", "reason": "one sentence in English that cites the maximum wait and the number of blocked sessions"}`;

return { json: { kb_severity: kb.kb_severity, kb_criterion: kb.kb_criterion, prompt } };
